let found=new Set();try{found=new Set(JSON.parse(localStorage.getItem('tpu-wow-found')||'[]'))}catch(e){found=new Set()};
const $=id=>document.getElementById(id);
function esc(s){return String(s).replace(/[&<>\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));}
function update(){ $('count').textContent=found.size; if(found.size===32){toast('🎉 Откри всички 32 природни героя!');} }
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',3200)}
function buildHotspots(){const h=$('hotspots');h.innerHTML=zones.map(z=>`<button class="hot" style="left:${z.x}%;top:${z.y}%" title="${esc(z.code)} — ${esc(z.heroName)}" aria-label="${esc(z.heroName)} — ${esc(z.code)}" data-name="${esc(z.heroName)}" onclick="openZone(${z.id})"><img src="${z.hero}" alt="${esc(z.heroName)}"><span class="hotStar">✦</span><span class="hotHint">Открий</span></button>`).join('')}
function openZone(id){
 const z=zones.find(a=>a.id===id); if(!z)return;
 window.__wowZoneId=id;
 $('zoneTitle').innerHTML=`${z.emoji} ${esc(z.code)} — ${esc(z.name)}`;
 $('zoneBody').innerHTML=`<div class="zonegrid"><div class="mapcard"><img src="${z.map}" alt="Карта ${esc(z.name)}"></div><aside class="side"><span class="pill">${esc(z.type)}</span><h2>${esc(z.theme)}</h2><p>🌿 Натисни героя и го открий!</p><img class="heroimage" src="${z.hero}" alt="${esc(z.heroName)}"><div class="heroName">${z.emoji} ${esc(z.heroName)}</div><span class="pill">Герой на зоната</span><div class="fact"><b>💡 Малка природна история</b><br>Този герой е визуална покана да разгледаш зоната и да продължиш към следващото природно откритие.</div><div class="buttons wowDetailNav"><button class="btn wowBackBtn" onclick="wowBack()">← Назад</button><button class="btn" onclick="openHero(${z.id})">📸 Виж героя</button><button class="btn" onclick="wowToMap()">🗺️ Към картата</button></div></aside></div>`;
 $('zoneOverlay').classList.add('open')
}
function openHero(id){
 const z=zones.find(a=>a.id===id); if(!z)return;
 window.__wowZoneId=id;
 found.add(z.code);try{localStorage.setItem('tpu-wow-found',JSON.stringify([...found]))}catch(e){}update();
 $('heroBody').innerHTML=`<img src="${z.hero}" alt="${esc(z.heroName)}"><h1>${z.emoji} ${esc(z.heroName)}</h1><span class="pill">Илюстративен герой · ${esc(z.code)} · илюстрация, не доказателство за присъствие</span><div class="fact"><b>🌿 Открий героя</b><br>Разгледай героя и се върни към зоната или картата, за да продължиш.</div><div class="buttons wowDetailNav"><button class="btn wowBackBtn" onclick="wowBack()">← Назад</button><button class="btn" onclick="wowToMap()">🗺️ Към картата</button><button class="btn" onclick="closeHero();openZone(${z.id})">📍 Виж зоната</button></div>`;
 $('heroOverlay').classList.add('open')
}
function wowBack(){
 const hero=$('heroOverlay'), zone=$('zoneOverlay'), nav=$('navOverlay'), stats=$('statsOverlay'), search=$('searchOverlay');
 if(hero&&hero.classList.contains('open')){closeHero();return}
 if(zone&&zone.classList.contains('open')){closeZone();return}
 if(search&&search.classList.contains('open')){closeSearch();return}
 if(stats&&stats.classList.contains('open')){closeStats();return}
 if(nav&&nav.classList.contains('open')){closeNav();return}
}
function wowToMap(){closeHero();closeZone();closeSearch();closeStats();closeNav();}
function closeZone(){$('zoneOverlay').classList.remove('open')}
function closeHero(){$('heroOverlay').classList.remove('open')}
function openSearch(){$('searchOverlay').classList.add('open');$('searchInput').focus();doSearch('')}
function closeSearch(){$('searchOverlay').classList.remove('open')}
function doSearch(q){q=q.toLowerCase().trim();let r=zones.filter(z=>(z.code+' '+z.name+' '+z.heroName+' '+z.theme).toLowerCase().includes(q));$('results').innerHTML=r.map(z=>`<div class="result" onclick="closeSearch();openZone(${z.id})">${z.emoji} <b>${esc(z.code)}</b> — ${esc(z.name)}<br><small>${esc(z.heroName)} · ${esc(z.theme)}</small></div>`).join('')||'<div style="padding:15px;color:#678">Няма намерени резултати.</div>'}
// Clicking the search area of the background (top-right) opens the real search dialog.
$('scene').addEventListener('click',e=>{const x=e.clientX/window.innerWidth,y=e.clientY/window.innerHeight;if(x>.77&&y<.20)openSearch();});
// Top category zones on the reference background: approximate clickable areas.
$('scene').addEventListener('click',e=>{const x=e.clientX/window.innerWidth,y=e.clientY/window.innerHeight;if(y>.13&&y<.22&&x<.55){openSearch();}});

function closeNav(){document.getElementById('navOverlay').classList.remove('open')}
function closeStats(){document.getElementById('statsOverlay').classList.remove('open')}
function esc2(s){return String(s).replace(/[&<>\"]/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[m]));}
const catRules={
 birds:z=>['🦅','🪶','🪽','🐦'].includes(z.emoji),
 animals:z=>['🦦','🐐','🦌','🐢'].includes(z.emoji),
 plants:z=>['🌸','🌳'].includes(z.emoji),
 habitats:z=>/место|гора|планин|ливад|гор|влаж|степ|долин|скали/i.test(z.theme+' '+z.name),
 water:z=>/язовир|река|вода|влаж|марица|езер/i.test(z.name+' '+z.theme),
 pollinators:z=>['🦋','🪲'].includes(z.emoji)
};
const catNames={birds:'🐦 Птици',animals:'🐾 Животни',plants:'🌼 Растения',habitats:'🌳 Местообитания',water:'💧 Води',pollinators:'🦋 Опрашители'};
function openAllMap(){closeNav();closeStats();closeZone();closeHero();if(typeof window.tpuGisOpen==='function'){window.tpuGisOpen();}else{toast('Картата не е достъпна.');}}
function openAllZones(){openNav('🗺️ Всички 32 зони',zones,'all')}
function openCategory(cat){openNav(catNames[cat],zones.filter(catRules[cat]),cat)}
function openNav(title,list,cat){
 document.getElementById('navTitle').textContent=title;
 document.getElementById('navBody').innerHTML='<p style="color:#66806f">Избери зона, за да я разгледаш. Натисни героя за снимка и природна история.</p><div class="filterGrid">'+list.map(z=>`<div class="filterCard" onclick="closeNav();openZone(${z.id})"><img src="${z.hero}" alt="${esc2(z.heroName)}"><b>${z.emoji} ${esc2(z.heroName)}</b><small>${esc2(z.code)} · ${esc2(z.name)}</small></div>`).join('')+'</div>' || '<p>Няма намерени герои.</p>';
 document.getElementById('navOverlay').classList.add('open');
}
function openStats(kind){
 const data={municipalities:['🏘️','18','общини','Териториалният обхват на WOW версията представя 18 общини със зонирани територии.'],settlements:['🏡','149','населени места','Зоните се пресичат пространствено с 149 населени места.'],maps:['🗺️','33','картографски листа','WOW представя обща карта и 33 индивидуални картографски листа.'],intersections:['📐','181 154','пространствени пресичания','Това е визуален мащаб на пространствения анализ — не означава 181 154 уникални територии.']}[kind];
 if(!data){return openAllZones()}
 document.getElementById('statsTitle').textContent=data[0]+' '+data[2];
 document.getElementById('statsBody').innerHTML=`<div class="infoGrid"><div class="infoTile"><strong>${data[1]}</strong>${data[2]}</div><div class="infoTile"><strong>32</strong>защитени зони</div><div class="infoTile"><strong>🌿</strong>природни герои</div></div><div class="fact" style="margin-top:16px"><b>💡 За WOW</b><br>${data[3]}</div><button class="miniBtn" onclick="closeStats();openAllZones()">🗺️ Към всички зони</button>`;
 document.getElementById('statsOverlay').classList.add('open');
}
let bottomPage=0;
function carouselPrev(){bottomPage=(bottomPage+31)%32;openZone(bottomPage+1)}
function carouselNext(){bottomPage=(bottomPage+1)%32;openZone(bottomPage+1)}


document.getElementById('navOverlay').addEventListener('click',e=>{if(e.target.id==='navOverlay')closeNav()});
document.getElementById('statsOverlay').addEventListener('click',e=>{if(e.target.id==='statsOverlay')closeStats()});
update();buildHotspots();

// WOW V2 safety: expose button handlers and make bare clicks fail gracefully.
window.addEventListener('error',e=>{try{toast('⚠️ WOW: '+e.message)}catch(_){}});
